<template>
  <section class="tool-page">
    <button class="back" @click="$emit('back')">← Back to tools</button>
    <div class="tool-title">
      <div><h2>{{ tool.name }}</h2><p>{{ tool.description }} Configure the fields below, run the tool, and review structured output. Browser-only tools do not send sensitive content to the server.</p></div>
      <button class="heart big" @click="$emit('favorite', tool.slug)">{{ favorites.includes(tool.slug) ? '♥' : '♡' }}</button>
    </div>
    <div class="runner">
      <div class="form">
        <template v-if="uploadTools.includes(tool.slug)">
          <label>Upload file<input type="file" @change="file=$event.target.files[0]"></label>
        </template>
        <template v-else>
          <label v-for="[key,label] in fieldsFor(tool.slug)" :key="key">{{ label }}
            <textarea v-if="isLongField(key)" v-model="input[key]"></textarea>
            <input v-else-if="typeof input[key] === 'boolean'" type="checkbox" v-model="input[key]">
            <input v-else v-model="input[key]">
          </label>
        </template>
        <button class="run" @click="run" :disabled="loading">{{ loading ? 'Running...' : 'Run Tool' }}</button>
        <p class="error" v-if="error">{{ error }}</p>
      </div>
      <pre class="output">{{ output == null ? 'Output will appear here.' : (typeof output === 'string' ? output : JSON.stringify(output,null,2)) }}</pre>
    </div>
  </section>
</template>
<script setup>
import { onMounted, ref, watch } from 'vue'
import yaml from 'js-yaml'
import * as TOML from '@ltd/j-toml'
import cronstrue from 'cronstrue'
import CryptoJS from 'crypto-js'
const props = defineProps({ tool:Object, favorites:{type:Array,default:()=>[]} })
defineEmits(['back','favorite'])
const uploadTools=['file-hash','metadata-extractor','string-finder','log-analyzer']
const input=ref({}), output=ref(null), loading=ref(false), error=ref(''), file=ref(null)
watch(()=>props.tool.slug, reset, {immediate:true})
function reset(){ input.value=defaultInput(props.tool.slug); output.value=null; error.value=''; if(props.tool.mode==='frontend'&&!['ssh-key-generator','jwt-decoder','cert-decoder'].includes(props.tool.slug)) setTimeout(run,0) }
function isLongField(k){return ['sample','pem','text','items','command','vars','case_description','note_body','timeline_event'].includes(k) || String(input.value[k]||'').includes('\n')}
function defaultInput(slug){ return ({'ping-traceroute':{target:'1.1.1.1',mode:'ping'},'port-scanner':{host:'scanme.nmap.org',start_port:22,end_port:85},'dns-lookup':{domain:'example.com',record_type:'A'},'reverse-dns':{ip:'8.8.8.8'},whois:{domain:'example.com'},'ssl-checker':{host:'example.com',port:443},'bgp-asn':{asn:'AS15169'},'ip-geolocation':{ip:'8.8.8.8'},'wake-on-lan':{mac:'00:11:22:33:44:55',broadcast:'255.255.255.255',port:9},'http-headers':{url:'https://example.com'},'response-time':{url:'https://example.com'},'nat-translator':{private_cidr:'192.168.1.0/24',public_cidr:'203.0.113.0/24',address:'192.168.1.50'},'rbl-checker':{ip:'8.8.8.8'},'smart-checker':{device:'/dev/sda',sample:''},'cve-lookup':{query:'CVE-2024-3094'},virustotal:{indicator:'8.8.8.8'},'ioc-scanner':{items:'8.8.8.8\nexample.com'},'unifi-client':{controller_url:'https://10.10.10.1',api_key:'',query:'00:11:22:33:44:55'},'subnet-calculator':{cidr:'192.168.10.0/24'},'bandwidth-calculator':{size:10,size_unit:'GB',bandwidth:100,bandwidth_unit:'Mbps'},'password-generator':{length:20,count:5,upper:true,lower:true,numbers:true,symbols:true,ambiguous:false},'password-strength':{password:'CorrectHorseBatteryStaple!2026'},'ssh-key-generator':{type:'RSA-2048'},'hash-tool':{text:'MRDTech',algorithm:'SHA-256',verify:''},'jwt-decoder':{jwt:''},base64:{mode:'encode',text:'MRDTech'},'cidr-rule-builder':{cidr:'10.10.10.0/24',action:'allow',port:'443',protocol:'tcp'},'docker-compose-converter':{command:'docker run -d --name web -p 8080:80 -e TZ=UTC nginx:latest'},'k8s-calculator':{replicas:3,cpu_request:250,cpu_limit:500,mem_request:256,mem_limit:512},'terraform-formatter':{vars:'region=string=us-east-1\ninstance_count=number=2'},'data-converter':{from:'json',to:'yaml',text:'{"name":"mrdtech","secure":true}'},'unifi-vlan':{name:'Servers',vlan_id:30,subnet:'10.10.30.0/24',gateway:'10.10.30.1'},'unifi-port-profile':{name:'AP Trunk',native_vlan:10,tagged_vlans:'20,30,40',voice_vlan:50},'cron-builder':{minute:'0',hour:'2',dom:'*',month:'*',dow:'*'},'uptime-calculator':{period_hours:720,downtime_minutes:43},'event-id':{id:4625},'syslog-severity':{level:4},'ldap-dn':{cn:'Michael Dziegiel',ous:'Users,MRDTech',dcs:'mrdtech,local'},'gpo-path':{domain:'mrdtech.local',guid:'{31B2F340-016D-11D2-945F-00C04FB984F9}'},'vlan-calculator':{vlan_id:30,mode:'trunk'},'cert-decoder':{pem:''},'case-manager':{case_action:'create',case_id:'',case_title:'Incident Review',case_description:'Initial case notes',note_body:'',evidence_name:'',evidence_kind:'disk image',evidence_sha256:'',timeline_event:'',occurred_at:''}})[slug]||{} }
function fieldsFor(slug){const f={'ping-traceroute':[['target','Target hostname or IP'],['mode','Mode: ping or traceroute']],'port-scanner':[['host','Host'],['start_port','Start port'],['end_port','End port']],'dns-lookup':[['domain','Domain'],['record_type','Record type']],whois:[['domain','Domain']],'ssl-checker':[['host','Hostname'],['port','Port']],'reverse-dns':[['ip','IP address']],'bgp-asn':[['asn','ASN like AS15169']],'ip-geolocation':[['ip','IP address']],'wake-on-lan':[['mac','MAC address'],['broadcast','Broadcast address'],['port','UDP port']],'http-headers':[['url','URL']],'response-time':[['url','URL']],'nat-translator':[['private_cidr','Private CIDR'],['public_cidr','Public CIDR'],['address','Private address']],'rbl-checker':[['ip','IP address']],'smart-checker':[['device','Device path'],['sample','Paste smartctl output instead of querying device']],'cve-lookup':[['query','CVE ID or keyword']],virustotal:[['indicator','URL, IP, domain, or hash']],'ioc-scanner':[['items','One IOC per line']],'unifi-client':[['controller_url','Controller URL'],['api_key','API key'],['query','MAC or IP']],'case-manager':[['case_action','Action: create, list, add_note, add_evidence, add_timeline, export, delete'],['case_id','Case ID for existing case'],['case_title','Case title'],['case_description','Description'],['note_body','Note body'],['evidence_name','Evidence name'],['evidence_kind','Evidence kind'],['evidence_sha256','Evidence SHA256'],['timeline_event','Timeline event'],['occurred_at','Occurred at ISO timestamp']]}; return f[slug] || Object.keys(defaultInput(slug)).map(k=>[k,k.replaceAll('_',' ')])}
function ipToNum(ip){return ip.split('.').reduce((a,o)=>((a<<8)+Number(o))>>>0,0)}
function numToIp(n){return [24,16,8,0].map(s=>(n>>>s)&255).join('.')}
function subnet(cidr){let [ip,p]=cidr.split('/');p=Number(p);let mask=(0xffffffff<<(32-p))>>>0,net=ipToNum(ip)&mask,bc=(net|(~mask>>>0))>>>0,hosts=Math.max(0,2**(32-p)-2);return{cidr,network:numToIp(net),broadcast:numToIp(bc),netmask:numToIp(mask),wildcard:numToIp((~mask)>>>0),first_usable:hosts?numToIp(net+1):null,last_usable:hosts?numToIp(bc-1):null,usable_hosts:hosts}}
function pem(label,buf){const b64=btoa(String.fromCharCode(...new Uint8Array(buf))).match(/.{1,64}/g).join('\n');return `-----BEGIN ${label}-----\n${b64}\n-----END ${label}-----`}
async function generateKeyPair(type){const bits=type.includes('4096')?4096:2048;const key=await crypto.subtle.generateKey({name:'RSASSA-PKCS1-v1_5',modulusLength:bits,publicExponent:new Uint8Array([1,0,1]),hash:'SHA-256'},true,['sign','verify']);return{type:`RSA-${bits}`,public_key_pem:pem('PUBLIC KEY',await crypto.subtle.exportKey('spki',key.publicKey)),private_key_pem:pem('PRIVATE KEY',await crypto.subtle.exportKey('pkcs8',key.privateKey)),note:'Generated locally in browser WebCrypto. Convert to OpenSSH format before production SSH deployment.'}}
function allHashes(text){return{md5:CryptoJS.MD5(text).toString(),sha1:CryptoJS.SHA1(text).toString(),sha256:CryptoJS.SHA256(text).toString(),sha512:CryptoJS.SHA512(text).toString()}}
async function frontendRun(slug,i){if(slug==='subnet-calculator')return subnet(i.cidr); if(slug==='vlan-calculator')return{vlan_id:i.vlan_id,range:Number(i.vlan_id)<=1005?'normal range':'extended range',reserved:'0, 1, 1002-1005, 4095',mode:i.mode,access:'Access ports carry one untagged VLAN.',trunk:'Trunks carry tagged VLANs using 802.1Q.',native:'Native VLAN is untagged on a trunk; do not use VLAN 1 in sane environments.'}; if(slug==='bandwidth-calculator'){let bytes=i.size*({KB:1e3,MB:1e6,GB:1e9,TB:1e12}[i.size_unit]||1),bps=i.bandwidth*({Kbps:1e3,Mbps:1e6,Gbps:1e9}[i.bandwidth_unit]||1),sec=bytes*8/bps;return{seconds:sec,human:`${Math.floor(sec/3600)}h ${Math.floor(sec%3600/60)}m ${Math.round(sec%60)}s`}} if(slug==='password-generator'){let sets=[i.upper&&'ABCDEFGHJKLMNPQRSTUVWXYZ',i.lower&&'abcdefghijkmnopqrstuvwxyz',i.numbers&&'23456789',i.symbols&&'!@#$%^&*_-+=?'].filter(Boolean).join(''); if(i.ambiguous)sets+='0OolI1'; return Array.from({length:i.count},()=>Array.from(crypto.getRandomValues(new Uint32Array(i.length))).map(n=>sets[n%sets.length]).join(''))} if(slug==='password-strength'){let classes=[/[a-z]/,/[A-Z]/,/\d/,/[^A-Za-z0-9]/].filter(r=>r.test(i.password)).length,pool=[26,26,10,32].slice(0,classes).reduce((a,b)=>a+b,0)||1,entropy=Math.round(i.password.length*Math.log2(pool));return{entropy_bits:entropy,score:entropy>100?'excellent':entropy>70?'strong':entropy>45?'fair':'weak'}} if(slug==='ssh-key-generator')return generateKeyPair(i.type); if(slug==='hash-tool'){let h=allHashes(i.text);return{...h,verified:i.verify?Object.values(h).includes(i.verify.toLowerCase()):null}} if(slug==='jwt-decoder'){let[h,p]=i.jwt.split('.');return{header:JSON.parse(atob((h||'').replace(/-/g,'+').replace(/_/g,'/'))||'{}'),payload:JSON.parse(atob((p||'').replace(/-/g,'+').replace(/_/g,'/'))||'{}'),verified:false}} if(slug==='base64')return i.mode==='decode'?atob(i.text):btoa(i.text); if(slug==='cidr-rule-builder')return{iptables:`iptables -A INPUT -p ${i.protocol} -s ${i.cidr} --dport ${i.port} -j ${i.action==='allow'?'ACCEPT':'DROP'}`,ufw:`ufw ${i.action} from ${i.cidr} to any port ${i.port} proto ${i.protocol}`,windows:`New-NetFirewallRule -DisplayName "STS ${i.action} ${i.cidr}" -Direction Inbound -RemoteAddress ${i.cidr} -Protocol ${i.protocol.toUpperCase()} -LocalPort ${i.port} -Action ${i.action==='allow'?'Allow':'Block'}`}; if(slug==='docker-compose-converter')return `services:\n  converted:\n    image: ${i.command.split(/\s+/).at(-1)}\n    restart: unless-stopped`; if(slug==='k8s-calculator')return{replicas:i.replicas,total_cpu_request_millicores:i.replicas*i.cpu_request,total_memory_request_mib:i.replicas*i.mem_request}; if(slug==='terraform-formatter')return i.vars.split('\n').filter(Boolean).map(l=>{let[n,t,d]=l.split('=');return`variable "${n}" {\n  type = ${t||'string'}\n  default = ${JSON.stringify(d||'')}\n}`}).join('\n\n'); if(slug==='data-converter'){let obj=i.from==='json'?JSON.parse(i.text):i.from==='yaml'?yaml.load(i.text):TOML.parse(i.text);return i.to==='json'?JSON.stringify(obj,null,2):i.to==='yaml'?yaml.dump(obj):TOML.stringify(obj)} if(slug==='unifi-vlan')return{name:i.name,purpose:'corporate',vlan_enabled:true,vlan:i.vlan_id,subnet:i.subnet,gateway:i.gateway}; if(slug==='unifi-port-profile')return{name:i.name,native_networkconf_id:i.native_vlan,tagged_vlans:String(i.tagged_vlans).split(',').map(x=>Number(x.trim())),voice_networkconf_id:Number(i.voice_vlan)||null}; if(slug==='cron-builder'){let expr=`${i.minute} ${i.hour} ${i.dom} ${i.month} ${i.dow}`;return{expression:expr,summary:cronstrue.toString(expr)}} if(slug==='uptime-calculator'){let mins=i.period_hours*60;return{uptime_percent:(100*((mins-i.downtime_minutes)/mins)).toFixed(5)}} if(slug==='event-id')return{event_id:i.id,description:'Built-in lookup for common Windows security/system events. Unknown IDs should be checked against Microsoft documentation.'}; if(slug==='syslog-severity')return{level:i.level,meaning:['Emergency','Alert','Critical','Error','Warning','Notice','Informational','Debug'][Number(i.level)]}; if(slug==='ldap-dn')return`CN=${i.cn},${String(i.ous).split(',').map(x=>'OU='+x.trim()).join(',')},${String(i.dcs).split(',').map(x=>'DC='+x.trim()).join(',')}`; if(slug==='gpo-path')return`\\${i.domain}\\SYSVOL\\${i.domain}\\Policies\\${i.guid}`; if(slug==='cert-decoder')return{pem_length:(i.pem||'').length,has_certificate:(i.pem||'').includes('BEGIN CERTIFICATE')}; return i}
async function run(){loading.value=true;error.value='';output.value=null;try{if(uploadTools.includes(props.tool.slug)){let fd=new FormData();fd.append('file',file.value);let r=await fetch(`/api/tools/${props.tool.slug}/upload`,{method:'POST',body:fd});output.value=await r.json();if(!r.ok)throw new Error(output.value.detail||'upload failed')}else if(props.tool.mode==='backend'){let r=await fetch(`/api/tools/${props.tool.slug}/run`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input.value)});output.value=await r.json();if(!r.ok)throw new Error(output.value.detail||'request failed')}else output.value=await frontendRun(props.tool.slug,input.value)}catch(e){error.value=e.message}finally{loading.value=false}}
</script>
